"use client";
import {useEffect,useRef,useState} from 'react';import {hotelClient,hotelRpc} from '@/lib/pilot';import {readCashJournalCandidates,type CashJournalSource,type CashJournalCandidate} from '@/lib/cashier-journal-candidates';import {bankCloseMoney} from '@/lib/cashier-bank-close';
type Props={source:CashJournalSource;disabled?:boolean;onSelect:(c:CashJournalCandidate|null)=>void};
export function CashierJournalSelect(p:Props){return <Selector key={[p.source.scope.tenant,p.source.scope.property,p.source.scope.actor,p.source.kind,p.source.source,p.source.account].join(':')} {...p}/>}
function Selector({source,disabled=false,onSelect}:Props){const [page,setPage]=useState<ReturnType<typeof readCashJournalCandidates>|null>(null),[selected,setSelected]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');const lock=useRef(false),alive=useRef(false),callback=useRef(onSelect);callback.current=onSelect;useEffect(()=>{alive.current=true;callback.current(null);return()=>{alive.current=false}},[]);
async function load(next=false){if(lock.current||disabled)return;lock.current=true;setBusy(true);setError('');setSelected('');callback.current(null);try{const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==source.scope.actor)throw Error('Sign-in changed. Reopen cash accounting.');const before=next?page?.next??null:null;const r=readCashJournalCandidates(await hotelRpc('cashier_journal_candidates',{p_tenant:source.scope.tenant,p_property:source.scope.property,p_kind:source.kind,p_source:source.source,p_account:source.account,p_before:before}),source,before);const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==source.scope.actor)throw Error('Sign-in changed. Reopen cash accounting.');if(alive.current)setPage(r)}catch(e){if(alive.current){setPage(null);setError(e instanceof Error?e.message:'Unable to load journals.')}}finally{lock.current=false;if(alive.current)setBusy(false)}}
return <fieldset disabled={disabled||busy}><legend>{source.kind==='opening'?'Opening cash journal':'Custody movement journal'}</legend><button type="button" onClick={()=>void load()}>Find eligible journals</button>{error&&<p role="alert">{error}</p>}{page&&(page.linked?<p>This cash source already has an active journal link.</p>:<><p>Required cash amount: {bankCloseMoney(page.cash)}. Review the journal purpose before selecting it.</p>{page.entries.length?<label>Journal to link<select value={selected} onChange={e=>{setSelected(e.target.value);callback.current(page.entries.find(c=>c.journal_id===e.target.value)??null)}}><option value="">Choose a journal</option>{page.entries.map(c=><option key={c.journal_id} value={c.journal_id}>{c.posting_date} — {c.description} — {bankCloseMoney(c.cash_minor)}</option>)}</select></label>:<p>No eligible journals on this page. Prepare a dedicated cash journal if needed.</p>}{page.next&&<button type="button" onClick={()=>void load(true)}>Next journal page</button>}</>)}</fieldset>}
